import { serve } from "https://deno.land/std@0.192.0/http/server.ts"
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.0"

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
}

serve(async (req) => {
  // Handle CORS
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    // 1. Get authenticated user
    const authHeader = req.headers.get('Authorization')
    if (!authHeader) {
      throw new Error('No authorization header')
    }

    const supabaseClient = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
      { global: { headers: { Authorization: authHeader } } }
    )

    const token = authHeader.replace('Bearer ', '').trim()
    const { data: { user }, error: userError } = await supabaseClient.auth.getUser(token)

    if (userError || !user) {
      throw new Error(`Unauthorized: ${userError?.message || 'No user found in getUser'}`)
    }

    // 2. Parse request body
    const { item_id, descricao, marca, referencia, unidade } = await req.json()
    if (!item_id || !descricao) {
      throw new Error('Missing item data (item_id, descricao)')
    }

    // 3. Get PDM Config from DB (Bypassing RLS for settings if needed, or using service_role)
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    )

    const { data: configRecord, error: configError } = await supabaseAdmin
      .from('sys_settings')
      .select('value')
      .eq('key', 'pdm_ai_config')
      .single()

    if (configError || !configRecord) {
      throw new Error('PDM config not found')
    }

    const config = configRecord.value as any

    if (!config.enabled) {
      return new Response(
        JSON.stringify({ message: "IA desativada." }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      )
    }

    // 4. Call Gemini AI
    const primaryModel = config.model || 'gemini-2.5-flash';
    const fallbackModel = 'gemini-2.5-flash';

    const aiPrompt = `${config.prompt}

Analise os seguintes dados do item:
Descrição: ${descricao}
Marca: ${marca || '-'}
Referência: ${referencia || '-'}
Unidade: ${unidade}

Retorne APENAS um JSON válido seguindo a estrutura:
{ 
  "status": "Aprovado" | "FALTANDO_INFO", 
  "message": "...", 
  "descricao_padronizada": "NOME PADRÃO AQUI (ou a estrutura esperada caso falte info)" 
}`

    const requestBody = JSON.stringify({
      contents: [{ parts: [{ text: aiPrompt }] }],
      generationConfig: { temperature: 0.1, responseMimeType: "application/json" }
    });

    const fetchGemini = async (model: string) => {
      const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${config.api_key}`;
      return await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: requestBody
      });
    };

    let aiResponse = await fetchGemini(primaryModel);

    // Fallback: Se o modelo primário atingir a cota (429) ou erro interno do Google, tentamos o fallback 2.5
    if (!aiResponse.ok && (aiResponse.status === 429 || aiResponse.status >= 500) && primaryModel !== fallbackModel) {
      console.warn(`Modelo ${primaryModel} falhou com status ${aiResponse.status}. Tentando fallback para ${fallbackModel}...`);
      aiResponse = await fetchGemini(fallbackModel);
    }

    if (!aiResponse.ok) {
      const errTxt = await aiResponse.text()
      console.error("Gemini Error:", errTxt)
      throw new Error(`Google Gemini API Error (${aiResponse.status}): ${errTxt}`)
    }

    const aiResult = await aiResponse.json()
    const textContent = aiResult.candidates[0].content.parts[0].text

    let parsedResult
    try {
      parsedResult = JSON.parse(textContent)
    } catch (e) {
      console.error("Failed to parse Gemini response:", textContent)
      parsedResult = { status: "FALTANDO_INFO", message: "Erro ao interpretar resposta da IA." }
    }

    // 5. Update Item in DB
    const { error: updateError } = await supabaseAdmin
      .from('itens_solicitacao')
      .update({
        analise_pdm_status: parsedResult.status,
        analise_pdm_msg: parsedResult.message,
        analise_pdm_padronizado: parsedResult.descricao_padronizada
      })
      .eq('id', item_id)

    if (updateError) {
      console.error("Failed to update item:", updateError)
      throw new Error(`Failed to save AI analysis: ${updateError.message}`)
    }

    return new Response(
      JSON.stringify({ success: true, result: parsedResult }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    )

  } catch (error: any) {
    console.error("Function error:", error.message)
    // Retornamos 200 para que o frontend (Supabase Client) não lance um FunctionsHttpError opaco
    return new Response(
      JSON.stringify({ success: false, error: error.message }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
    )
  }
})
